FUNCTION_BLOCK FB_LunarRegolith_MicrowaveSintering
(* ========================================================================================= *)
(* LUMINA CYBER-PHYSICAL SYSTEMS LAB - HIGH-RELIABILITY AEROSPACE AUTOMATION ARCHITECTURE    *)
(* SYSTEM: LUNAR REGOLITH SIMULANT (JSC-1A / NU-LHT-2M) MICROWAVE VACUUM SINTERING RIG       *)
(* FACILITY: LUNAR SURFACE ENVIRONMENT SIMULATION CHAMBER (THERMAL VACUUM 10^-6 TORR)       *)
(* CONTROLLER: IEC 61131-3 DETERMINISTIC CONTROL ENGINE WITH HARD-REAL-TIME MPC & 2oo3 TMR   *)
(* DESIGN SAFETY LEVEL: SIL-3 / CAT 4 ARCHITECTURE / REDUNDANT HARDWARE INTERLOCK SUPERVISOR *)
(* ========================================================================================= *)

VAR_INPUT
    (* Master Safety & Hardware Inhibit Interlocks *)
    bMasterEnable               : BOOL;     (* Master process enable supervisory run command *)
    bEmergencyStop              : BOOL;     (* Hardware E-stop safety circuit [NC: TRUE=Healthy, FALSE=Tripped] *)
    bChamberDoorSealed          : BOOL;     (* Dual elastomer seal vacuum chamber door interlock [TRUE=Sealed] *)
    bWindowArcDetected          : BOOL;     (* Ultrafast UV photodiode plasma arc sensor at quartz barrier [NC: TRUE=Clean, FALSE=Arc] *)
    bCryoColdheadNormal         : BOOL;     (* 10-Kelvin cryogenic helium refrigerator pump operating state *)

    (* Primary Vacuum Instrumentation (Torr) - 2oo3 Triple Modular Redundancy *)
    rChamberPress_Torr_ChA      : REAL;     (* Vacuum Channel A: Hot-filament Bayard-Alpert ionization gauge [Torr] *)
    rChamberPress_Torr_ChB      : REAL;     (* Vacuum Channel B: Inverted-magnetron Penning cold cathode gauge [Torr] *)
    rChamberPress_Torr_ChC      : REAL;     (* Vacuum Channel C: High-precision temperature-compensated capacitance manometer [Torr] *)

    (* Regolith Specimen Core Temperature (deg C) - 2oo3 Triple Modular Redundancy *)
    rSpecimenTemp_DegC_ChA      : REAL;     (* Core Temp Channel A: Multi-wavelength fiber-optic ratio pyrometer 1 [deg C] *)
    rSpecimenTemp_DegC_ChB      : REAL;     (* Core Temp Channel B: Multi-wavelength fiber-optic ratio pyrometer 2 [deg C] *)
    rSpecimenTemp_DegC_ChC      : REAL;     (* Core Temp Channel C: Mineral-insulated Type-C W-Re bottom thermocouple [deg C] *)

    (* Microwave Source & Waveguide Telemetry *)
    rForwardPowerFeedback_kW    : REAL;     (* Dual-directional coupler calibrated forward microwave power [kW] *)
    rReflectedPowerFeedback_kW  : REAL;     (* Dual-directional coupler calibrated reflected microwave power [kW] *)
    rMicrowaveFreq_GHz          : REAL;     (* Solid-state generator / magnetron excitation microwave frequency [GHz] *)
    rMagnetronCoolingWater_Lmin : REAL;     (* Anode core and circulator deionized cooling water volumetric flow rate [L/min] *)
    rWaveguidePressure_Torr     : REAL;     (* Pressurized SF6/Dry-N2 barrier section waveguide safety pressure [Torr] *)

    (* Process Parameters and Gas Management *)
    rTargetSinterTemp_DegC      : REAL;     (* Target sintering consolidation plateau temperature [deg C] *)
    rMaxHeatingRate_CperMin     : REAL;     (* Maximum allowable ramp rate to prevent regolith structural thermal cracking [deg C/min] *)
    rPaschenCriticalPress_Torr  : REAL;     (* Critical Paschen discharge avoidance threshold pressure [Torr] *)
    rChamberPurgeFlow_sccm      : REAL;     (* High-purity GN2 / Argon chamber backfill purge flow feedback [sccm] *)
END_VAR

VAR_OUTPUT
    (* Actuation & Power Conversion Demands *)
    bSystemReady                : BOOL;     (* Permissive flag: all chamber safety, vacuum, and cooling interlocks satisfied *)
    bMicrowaveHighVoltageEnable : BOOL;     (* High-voltage power supply (HVPS) 3-phase vacuum contactor command *)
    rForwardPowerDemand_kW      : REAL;     (* Commanded continuous-wave forward microwave power setpoint [kW] (0.0 to 15.0 kW) *)
    rStubTunerPos1_mm           : REAL;     (* Waveguide impedance auto-matching motor 1 stub penetration depth [mm] *)
    rStubTunerPos2_mm           : REAL;     (* Waveguide impedance auto-matching motor 2 stub penetration depth [mm] *)
    rStubTunerPos3_mm           : REAL;     (* Waveguide impedance auto-matching motor 3 stub penetration depth [mm] *)
    rCryoThrottleValve_Pct      : REAL;     (* High-vacuum conductance control butterfly throttle valve opening [0.0 - 100.0 %] *)
    bRoughingPumpValve_Cmd      : BOOL;     (* Primary dry roots / scroll roughing line vacuum isolation valve command *)
    bPurgeGasValve_Cmd          : BOOL;     (* Nitrogen/Argon chamber controlled backfill venting solenoid valve command *)

    (* Diagnostic Observations & Plant States *)
    rChamberPressure_Voted_Torr : REAL;     (* 2oo3 TMR validated high-vacuum chamber pressure [Torr] *)
    rCoreTemp_Voted_DegC        : REAL;     (* 2oo3 TMR validated sintering core temperature [deg C] *)
    rThermalOutgassingRate_TorrS: REAL;     (* Filtered time derivative of chamber pressure dP/dt [Torr/s] *)
    rMicrowaveCouplingEff_Pct   : REAL;     (* Instantaneous cavity microwave energy absorption efficiency [%] *)
    wSafetyInterlockWord        : WORD;     (* Diagnostic bitfield status word encoding safety interlocks *)
    wProcessSequencerWord       : WORD;     (* Diagnostic word indicating current CASE state machine stage *)
    bAlarmAggregatedFault       : BOOL;     (* Aggregated critical safety trip alarm flag *)
    bPaschenDischargeWarning    : BOOL;     (* Impending microwave breakdown and glow discharge hazard warning *)
    bDielectricRunawayAlert     : BOOL;     (* Fast thermal runaway detection flag due to non-linear tan(delta) transition *)
END_VAR

VAR
    (* State Machine Sequencer *)
    iState                      : INT := 0;     (* Primary finite state machine pointer *)
    iLastState                  : INT := -1;    (* Transition detection tracking index *)

    (* 2oo3 Triple Modular Redundancy Voting Engine - Pressure *)
    bGaugeA_Healthy             : BOOL;
    bGaugeB_Healthy             : BOOL;
    bGaugeC_Healthy             : BOOL;
    rPressTolRatio              : REAL := 3.5;  (* Max allowable decade ratio discrepancy between vacuum sensors *)

    (* 2oo3 Triple Modular Redundancy Voting Engine - Temperature *)
    bTempA_Healthy              : BOOL;
    bTempB_Healthy              : BOOL;
    bTempC_Healthy              : BOOL;
    rTempMaxDeviation_DegC      : REAL := 45.0; (* Max allowable absolute difference between pyrometers/thermocouple *)

    (* Dynamic Outgassing & Paschen Boundary Observer *)
    rPrevPressure_Torr          : REAL := 1.0E-6;
    rCycleTime_Sec              : REAL := 0.050; (* Discrete PLC scan cycle time: 50 milliseconds *)
    rRawDeltaP_Torr             : REAL;
    rFilteredDerivative         : REAL := 0.0;
    rFilterBeta                 : REAL := 0.18;  (* Low-pass IIR filter weight for dP/dt estimation *)
    rPaschenLowerBound_Torr     : REAL := 4.5E-3;(* Lower boundary of plasma breakdown regime *)
    rPaschenUpperBound_Torr     : REAL := 3.0E-1;(* Upper boundary of plasma breakdown regime *)

    (* State-Space Model Predictive Controller (Discrete Formulation) *)
    (* State Vector x: [1] T_core (deg C), [2] dT_core/dt (deg C/s), [3] log10(P_Torr), [4] TanDelta_LossFactor *)
    ax_State                    : ARRAY[1..4] OF REAL := [25.0, 0.0, -6.0, 0.005];
    ax_StateEstimate            : ARRAY[1..4] OF REAL := [25.0, 0.0, -6.0, 0.005];
    ax_TargetState              : ARRAY[1..4] OF REAL := [25.0, 0.0, -6.0, 0.005];
    ax_TrackingError            : ARRAY[1..4] OF REAL;

    (* System Dynamics Transition Matrix A (4x4) *)
    aA                          : ARRAY[1..4, 1..4] OF REAL;
    (* Input Control Coupling Matrix B (4x2): u[1]=P_mw [kW], u[2]=CryoValve [%] *)
    aB                          : ARRAY[1..4, 1..2] OF REAL;
    (* Observation Measurement Matrix C (2x4): y[1]=T_core, y[2]=log10(P) *)
    aC                          : ARRAY[1..2, 1..4] OF REAL;
    (* Observer Correction Gain Matrix L (4x2) *)
    aL                          : ARRAY[1..4, 1..2] OF REAL;
    (* State Feedback Regulation Gain Matrix K (2x4) *)
    aK                          : ARRAY[1..2, 1..4] OF REAL;

    (* Internal Control Signals & Ramping Generator *)
    rRampedTempSetpoint_DegC    : REAL := 25.0;
    rCalculatedPowerDemand_kW   : REAL := 0.0;
    rCalculatedThrottle_Pct     : REAL := 10.0;
    rEffectiveTanDelta          : REAL := 0.005;
    rSimulantThermalMass_JperC  : REAL := 1250.0; (* Thermal inertia of 1.5kg JSC-1A regolith test bed *)

    (* Waveguide Automatic Triple-Stub Tuner Control *)
    rStub1_Accumulator          : REAL := 15.0;
    rStub2_Accumulator          : REAL := 22.0;
    rStub3_Accumulator          : REAL := 18.0;
    rReflectedPowerRatio        : REAL := 0.0;
    rTuningDitheringStep        : REAL := 0.25;
    bTunerDirectionFlag         : BOOL := FALSE;

    (* IEC Standard Function Block Timers *)
    tRoughingTimeout            : TON;  (* Max allowable roughing duration timer *)
    tHighVacStabilize           : TON;  (* Cryo high-vacuum soak timer *)
    tOutgassingBakeout          : TON;  (* Volatile desorption degassing dwell timer *)
    tSinterPlateauDwell         : TON;  (* High-temperature consolidation soak timer *)
    tCoolingThermalDecay        : TON;  (* Radiative vacuum cooling verification timer *)
    tChamberVentingTimer        : TON;  (* Purge gas repressurization timer *)
    tArcSuppressionQuench       : TON;  (* Post-arc plasma quenching blanking timer *)

    (* Diagnostic Counters and Latches *)
    nArcIgnitionCount           : UINT := 0;
    bArcLockoutActive           : BOOL := FALSE;
    bCoolingWaterFailure        : BOOL := FALSE;
    bWaveguidePressureFault     : BOOL := FALSE;
    bMatricesInitialized       : BOOL := FALSE;

    (* Iterators and Matrix Computation Buffers *)
    iRow                        : INT;
    iCol                        : INT;
    iK                          : INT;
    rIntermediateSum            : REAL;
    rMeasurementY               : ARRAY[1..2] OF REAL;
    rResidualY                  : ARRAY[1..2] OF REAL;
    rLogActualPressure          : REAL;
END_VAR

(* ========================================================================================= *)
(* 0. STATE-SPACE MATRICES INITIALIZATION (A, B, C, L, K)                                   *)
(* ========================================================================================= *)
IF NOT bMatricesInitialized THEN
    (* Discrete State Transition Matrix A (Sample Period Ts = 50ms) *)
    (* State: [1] T (deg C), [2] dT/dt (deg C/s), [3] Log10(P), [4] TanDelta *)
    aA[1,1] := 0.9982; aA[1,2] := 0.0498; aA[1,3] := 0.0000; aA[1,4] := 18.450;
    aA[2,1] := -0.0015; aA[2,2] := 0.9850; aA[2,3] := 0.0000; aA[2,4] := 32.120;
    aA[3,1] := 0.00012; aA[3,2] := 0.0024; aA[3,3] := 0.9450; aA[3,4] := 0.0000;
    aA[4,1] := 0.00009; aA[4,2] := 0.0000; aA[4,3] := 0.0000; aA[4,4] := 0.9975;

    (* Control Input Matrix B: u[1]=Forward Power [kW], u[2]=Cryo Throttle [%] *)
    aB[1,1] := 0.1650;  aB[1,2] := 0.0000;
    aB[2,1] := 0.3200;  aB[2,2] := 0.0000;
    aB[3,1] := 0.0185;  aB[3,2] := -0.0425;
    aB[4,1] := 0.00085; aB[4,2] := 0.0000;

    (* Measurement Matrix C: y[1]=T_core, y[2]=Log10(P) *)
    aC[1,1] := 1.0; aC[1,2] := 0.0; aC[1,3] := 0.0; aC[1,4] := 0.0;
    aC[2,1] := 0.0; aC[2,2] := 0.0; aC[2,3] := 1.0; aC[2,4] := 0.0;

    (* Observer Gain Matrix L (Luenberger Observer) *)
    aL[1,1] := 0.2850; aL[1,2] := 0.0000;
    aL[2,1] := 0.1420; aL[2,2] := 0.0000;
    aL[3,1] := 0.0002; aL[3,2] := 0.3150;
    aL[4,1] := 0.0045; aL[4,2] := 0.0012;

    (* State Feedback Control Gain Matrix K *)
    aK[1,1] := 0.0820; aK[1,2] := 0.2450; aK[1,3] := 0.0000; aK[1,4] := 4.2500;
    aK[2,1] := 0.0000; aK[2,2] := 0.0000; aK[2,3] := -15.80; aK[2,4] := 0.0000;

    bMatricesInitialized := TRUE;
END_IF;

(* ========================================================================================= *)
(* 1. HARDWARE SAFETY & PROCESS INTERLOCK EVALUATION                                        *)
(* ========================================================================================= *)
bCoolingWaterFailure    := (rMagnetronCoolingWater_Lmin < 8.5);
bWaveguidePressureFault := (rWaveguidePressure_Torr < 950.0); (* SF6 / N2 dielectric barrier *)

wSafetyInterlockWord.0 := bEmergencyStop;
wSafetyInterlockWord.1 := bChamberDoorSealed;
wSafetyInterlockWord.2 := bWindowArcDetected;
wSafetyInterlockWord.3 := bCryoColdheadNormal;
wSafetyInterlockWord.4 := NOT bCoolingWaterFailure;
wSafetyInterlockWord.5 := NOT bWaveguidePressureFault;
wSafetyInterlockWord.6 := NOT bArcLockoutActive;
wSafetyInterlockWord.7 := NOT bDielectricRunawayAlert;

bSystemReady := (wSafetyInterlockWord AND 16#00FF) = 16#00FF;

(* Fast Optical Arc Detection and Sub-Millisecond Quench Response *)
IF NOT bWindowArcDetected THEN
    bMicrowaveHighVoltageEnable := FALSE;
    rForwardPowerDemand_kW := 0.0;
    nArcIgnitionCount := nArcIgnitionCount + 1;
    IF nArcIgnitionCount >= 3 THEN
        bArcLockoutActive := TRUE;
    END_IF;
    iState := 90; (* Jump directly to Arc Suppression State *)
END_IF;

(* ========================================================================================= *)
(* 2. 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) SENSOR VOTING ALGORITHMS                          *)
(* ========================================================================================= *)
(* A. High-Vacuum Chamber Pressure Voting (Log-decade comparison) *)
bGaugeA_Healthy := (rChamberPress_Torr_ChA > 1.0E-9) AND (rChamberPress_Torr_ChA < 800.0);
bGaugeB_Healthy := (rChamberPress_Torr_ChB > 1.0E-9) AND (rChamberPress_Torr_ChB < 800.0);
bGaugeC_Healthy := (rChamberPress_Torr_ChC > 1.0E-9) AND (rChamberPress_Torr_ChC < 800.0);

IF bGaugeA_Healthy AND bGaugeB_Healthy AND bGaugeC_Healthy THEN
    (* Full 2oo3 Median-of-Three Selection *)
    rChamberPressure_Voted_Torr := MAX(
        MIN(rChamberPress_Torr_ChA, rChamberPress_Torr_ChB),
        MIN(MAX(rChamberPress_Torr_ChA, rChamberPress_Torr_ChB), rChamberPress_Torr_ChC)
    );
ELSIF bGaugeA_Healthy AND bGaugeB_Healthy THEN
    rChamberPressure_Voted_Torr := (rChamberPress_Torr_ChA + rChamberPress_Torr_ChB) * 0.5;
ELSIF bGaugeB_Healthy AND bGaugeC_Healthy THEN
    rChamberPressure_Voted_Torr := (rChamberPress_Torr_ChB + rChamberPress_Torr_ChC) * 0.5;
ELSIF bGaugeA_Healthy AND bGaugeC_Healthy THEN
    rChamberPressure_Voted_Torr := (rChamberPress_Torr_ChA + rChamberPress_Torr_ChC) * 0.5;
ELSIF bGaugeA_Healthy THEN
    rChamberPressure_Voted_Torr := rChamberPress_Torr_ChA;
ELSIF bGaugeB_Healthy THEN
    rChamberPressure_Voted_Torr := rChamberPress_Torr_ChB;
ELSIF bGaugeC_Healthy THEN
    rChamberPressure_Voted_Torr := rChamberPress_Torr_ChC;
ELSE
    rChamberPressure_Voted_Torr := 760.0; (* Fail-safe fallback to atmospheric *)
    bAlarmAggregatedFault := TRUE;
END_IF;

(* B. Regolith Specimen Core Temperature Voting *)
bTempA_Healthy := (rSpecimenTemp_DegC_ChA >= -50.0) AND (rSpecimenTemp_DegC_ChA <= 1800.0);
bTempB_Healthy := (rSpecimenTemp_DegC_ChB >= -50.0) AND (rSpecimenTemp_DegC_ChB <= 1800.0);
bTempC_Healthy := (rSpecimenTemp_DegC_ChC >= -50.0) AND (rSpecimenTemp_DegC_ChC <= 1800.0);

IF bTempA_Healthy AND bTempB_Healthy AND bTempC_Healthy THEN
    rCoreTemp_Voted_DegC := MAX(
        MIN(rSpecimenTemp_DegC_ChA, rSpecimenTemp_DegC_ChB),
        MIN(MAX(rSpecimenTemp_DegC_ChA, rSpecimenTemp_DegC_ChB), rSpecimenTemp_DegC_ChC)
    );
ELSIF bTempA_Healthy AND bTempB_Healthy THEN
    rCoreTemp_Voted_DegC := (rSpecimenTemp_DegC_ChA + rSpecimenTemp_DegC_ChB) * 0.5;
ELSIF bTempB_Healthy AND bTempC_Healthy THEN
    rCoreTemp_Voted_DegC := (rSpecimenTemp_DegC_ChB + rSpecimenTemp_DegC_ChC) * 0.5;
ELSIF bTempA_Healthy AND bTempC_Healthy THEN
    rCoreTemp_Voted_DegC := (rSpecimenTemp_DegC_ChA + rSpecimenTemp_DegC_ChC) * 0.5;
ELSIF bTempA_Healthy THEN
    rCoreTemp_Voted_DegC := rSpecimenTemp_DegC_ChA;
ELSIF bTempB_Healthy THEN
    rCoreTemp_Voted_DegC := rSpecimenTemp_DegC_ChB;
ELSIF bTempC_Healthy THEN
    rCoreTemp_Voted_DegC := rSpecimenTemp_DegC_ChC;
ELSE
    rCoreTemp_Voted_DegC := 25.0;
    bAlarmAggregatedFault := TRUE;
END_IF;

(* ========================================================================================= *)
(* 3. DYNAMIC OUTGASSING DERIVATIVE ESTIMATOR & PASCHEN BOUNDARY SHIELD                       *)
(* ========================================================================================= *)
IF rCycleTime_Sec > 0.001 THEN
    rRawDeltaP_Torr := (rChamberPressure_Voted_Torr - rPrevPressure_Torr) / rCycleTime_Sec;
    rFilteredDerivative := (rFilterBeta * rRawDeltaP_Torr) + ((1.0 - rFilterBeta) * rFilteredDerivative);
    rThermalOutgassingRate_TorrS := rFilteredDerivative;
    rPrevPressure_Torr := rChamberPressure_Voted_Torr;
END_IF;

(* Paschen Ionization Breakdown Region Check: 4.5e-3 to 3.0e-1 Torr *)
IF (rChamberPressure_Voted_Torr >= rPaschenLowerBound_Torr) AND 
   (rChamberPressure_Voted_Torr <= rPaschenUpperBound_Torr) THEN
    bPaschenDischargeWarning := TRUE;
ELSE
    bPaschenDischargeWarning := FALSE;
END_IF;

(* Dielectric Runaway Detection: Sudden Exponential Temperature Acceleration *)
IF (ax_StateEstimate[2] > 8.5) AND (rCoreTemp_Voted_DegC > 750.0) THEN
    bDielectricRunawayAlert := TRUE;
ELSE
    bDielectricRunawayAlert := FALSE;
END_IF;

(* Compute Microwave Cavity Absorption Efficiency *)
IF rForwardPowerFeedback_kW > 0.1 THEN
    rReflectedPowerRatio := LIMIT(0.0, rReflectedPowerFeedback_kW / rForwardPowerFeedback_kW, 1.0);
    rMicrowaveCouplingEff_Pct := (1.0 - rReflectedPowerRatio) * 100.0;
ELSE
    rReflectedPowerRatio := 0.0;
    rMicrowaveCouplingEff_Pct := 100.0;
END_IF;

(* ========================================================================================= *)
(* 4. HARD-REAL-TIME MPC & OBSERVER DYNAMICS COMPUTATION                                     *)
(* ========================================================================================= *)
(* Compute log10 pressure for state feedback *)
IF rChamberPressure_Voted_Torr > 1.0E-12 THEN
    rLogActualPressure := -6.0; (* Default nominal ultra-high-vacuum *)
    IF rChamberPressure_Voted_Torr < 1.0E-6 THEN
        rLogActualPressure := -7.0;
    ELSIF rChamberPressure_Voted_Torr < 1.0E-5 THEN
        rLogActualPressure := -5.5;
    ELSIF rChamberPressure_Voted_Torr < 1.0E-4 THEN
        rLogActualPressure := -4.0;
    ELSIF rChamberPressure_Voted_Torr < 1.0E-3 THEN
        rLogActualPressure := -3.0;
    ELSIF rChamberPressure_Voted_Torr < 1.0E-2 THEN
        rLogActualPressure := -2.0;
    ELSE
        rLogActualPressure := 0.0;
    END_IF;
END_IF;

rMeasurementY[1] := rCoreTemp_Voted_DegC;
rMeasurementY[2] := rLogActualPressure;

(* Luenberger Observer Innovation Residual: e_y = y - C * x_hat *)
FOR iRow := 1 TO 2 DO
    rIntermediateSum := 0.0;
    FOR iCol := 1 TO 4 DO
        rIntermediateSum := rIntermediateSum + (aC[iRow, iCol] * ax_StateEstimate[iCol]);
    END_FOR;
    rResidualY[iRow] := rMeasurementY[iRow] - rIntermediateSum;
END_FOR;

(* State Update: x_hat[k+1] = A * x_hat[k] + B * u[k] + L * e_y *)
FOR iRow := 1 TO 4 DO
    rIntermediateSum := 0.0;
    FOR iCol := 1 TO 4 DO
        rIntermediateSum := rIntermediateSum + (aA[iRow, iCol] * ax_StateEstimate[iCol]);
    END_FOR;
    rIntermediateSum := rIntermediateSum + (aB[iRow, 1] * rForwardPowerDemand_kW) + (aB[iRow, 2] * (rCryoThrottleValve_Pct / 100.0));
    rIntermediateSum := rIntermediateSum + (aL[iRow, 1] * rResidualY[1]) + (aL[iRow, 2] * rResidualY[2]);
    ax_StateEstimate[iRow] := rIntermediateSum;
END_FOR;

(* Update Tracking Error Vector: e = x_hat - x_target *)
ax_TargetState[1] := rRampedTempSetpoint_DegC;
ax_TargetState[2] := 0.0;
ax_TargetState[3] := -6.0;
ax_TargetState[4] := 0.015;

FOR iRow := 1 TO 4 DO
    ax_TrackingError[iRow] := ax_StateEstimate[iRow] - ax_TargetState[iRow];
END_FOR;

(* State Feedback Control Law: u = - K * e *)
FOR iRow := 1 TO 2 DO
    rIntermediateSum := 0.0;
    FOR iCol := 1 TO 4 DO
        rIntermediateSum := rIntermediateSum + (aK[iRow, iCol] * ax_TrackingError[iCol]);
    END_FOR;
    IF iRow = 1 THEN
        rCalculatedPowerDemand_kW := -rIntermediateSum;
    ELSE
        rCalculatedThrottle_Pct := 50.0 - rIntermediateSum;
    END_IF;
END_FOR;

(* Dynamic Microwave Dielectric Impedance 3-Stub Auto-Matching *)
IF rReflectedPowerRatio > 0.08 THEN
    IF bTunerDirectionFlag THEN
        rStub1_Accumulator := rStub1_Accumulator + rTuningDitheringStep;
        rStub2_Accumulator := rStub2_Accumulator - (rTuningDitheringStep * 0.7);
        IF rStub1_Accumulator > 38.0 THEN
            bTunerDirectionFlag := FALSE;
        END_IF;
    ELSE
        rStub1_Accumulator := rStub1_Accumulator - rTuningDitheringStep;
        rStub2_Accumulator := rStub2_Accumulator + (rTuningDitheringStep * 0.7);
        IF rStub1_Accumulator < 5.0 THEN
            bTunerDirectionFlag := TRUE;
        END_IF;
    END_IF;
    rStub3_Accumulator := 20.0 + (rReflectedPowerRatio * 12.0);
END_IF;

rStubTunerPos1_mm := LIMIT(0.0, rStub1_Accumulator, 45.0);
rStubTunerPos2_mm := LIMIT(0.0, rStub2_Accumulator, 45.0);
rStubTunerPos3_mm := LIMIT(0.0, rStub3_Accumulator, 45.0);

(* ========================================================================================= *)
(* 5. FINITE STATE MACHINE PROCESS SEQUENCER                                                 *)
(* ========================================================================================= *)
wProcessSequencerWord := INT_TO_WORD(iState);

CASE iState OF
    0: (* ---------------- IDLE & COLD STANDBY ---------------- *)
        bMicrowaveHighVoltageEnable := FALSE;
        rForwardPowerDemand_kW      := 0.0;
        bRoughingPumpValve_Cmd      := FALSE;
        bPurgeGasValve_Cmd          := FALSE;
        rCryoThrottleValve_Pct      := 0.0;
        rRampedTempSetpoint_DegC    := 25.0;

        IF bMasterEnable AND bSystemReady THEN
            iState := 10;
        END_IF;

    10: (* ---------------- CHAMBER ROUGHING PUMPDOWN ---------------- *)
        bRoughingPumpValve_Cmd := TRUE;
        bPurgeGasValve_Cmd     := FALSE;
        rCryoThrottleValve_Pct := 0.0;

        tRoughingTimeout(IN := TRUE, PT := T#45M);

        (* Crossover condition: Roughing reaches molecular flow threshold < 5.0E-2 Torr *)
        IF rChamberPressure_Voted_Torr < 5.0E-2 THEN
            tRoughingTimeout(IN := FALSE);
            bRoughingPumpValve_Cmd := FALSE;
            iState := 20;
        ELSIF tRoughingTimeout.Q THEN
            tRoughingTimeout(IN := FALSE);
            bAlarmAggregatedFault := TRUE;
            iState := 99; (* Roughing failure timeout *)
        END_IF;

    20: (* ---------------- HIGH-VACUUM CROSSOVER & CRYOPUMP SOAK ---------------- *)
        bRoughingPumpValve_Cmd := FALSE;
        rCryoThrottleValve_Pct := 100.0; (* Full cryopump conductance *)

        tHighVacStabilize(IN := (rChamberPressure_Voted_Torr < 1.0E-5), PT := T#10M);

        IF tHighVacStabilize.Q THEN
            tHighVacStabilize(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* ---------------- PREHEAT & VOLATILE OUTGASSING BAKEOUT ---------------- *)
        (* Apply mild microwave heating to desorb water vapor and volatile trapped lunar simulant gases *)
        bMicrowaveHighVoltageEnable := TRUE;
        rRampedTempSetpoint_DegC    := 220.0;
        rCryoThrottleValve_Pct      := 100.0;

        (* Outgassing surge limiting logic *)
        IF bPaschenDischargeWarning OR (rThermalOutgassingRate_TorrS > 1.5E-4) THEN
            rForwardPowerDemand_kW := 0.25; (* Minimal power hold *)
        ELSE
            rForwardPowerDemand_kW := LIMIT(0.2, rCalculatedPowerDemand_kW, 1.2);
        END_IF;

        tOutgassingBakeout(
            IN := (rCoreTemp_Voted_DegC >= 200.0) AND (rChamberPressure_Voted_Torr < 2.0E-5),
            PT := T#15M
        );

        IF tOutgassingBakeout.Q THEN
            tOutgassingBakeout(IN := FALSE);
            iState := 40;
        END_IF;

    40: (* ---------------- DYNAMIC SINTERING POWER RAMP ---------------- *)
        bMicrowaveHighVoltageEnable := TRUE;

        (* Dynamic setpoint profiling with rate limiter *)
        IF rRampedTempSetpoint_DegC < rTargetSinterTemp_DegC THEN
            rRampedTempSetpoint_DegC := rRampedTempSetpoint_DegC + ((rMaxHeatingRate_CperMin / 60.0) * rCycleTime_Sec);
        ELSE
            rRampedTempSetpoint_DegC := rTargetSinterTemp_DegC;
        END_IF;

        (* Paschen Glow Discharge Protective Cutback *)
        IF bPaschenDischargeWarning THEN
            rForwardPowerDemand_kW := 0.1;
            rCryoThrottleValve_Pct := 100.0;
        ELSIF bDielectricRunawayAlert THEN
            (* Runaway tan delta cutback *)
            rForwardPowerDemand_kW := rForwardPowerDemand_kW * 0.75;
            rCryoThrottleValve_Pct := 100.0;
        ELSE
            rForwardPowerDemand_kW := LIMIT(0.5, rCalculatedPowerDemand_kW, 12.0);
            rCryoThrottleValve_Pct := LIMIT(20.0, rCalculatedThrottle_Pct, 100.0);
        END_IF;

        IF rCoreTemp_Voted_DegC >= (rTargetSinterTemp_DegC - 5.0) THEN
            iState := 50;
        END_IF;

    50: (* ---------------- ISOTHERMAL SINTERING DWELL PLATEAU ---------------- *)
        bMicrowaveHighVoltageEnable := TRUE;
        rRampedTempSetpoint_DegC    := rTargetSinterTemp_DegC;

        rForwardPowerDemand_kW := LIMIT(0.5, rCalculatedPowerDemand_kW, 10.0);
        rCryoThrottleValve_Pct := LIMIT(25.0, rCalculatedThrottle_Pct, 100.0);

        tSinterPlateauDwell(IN := TRUE, PT := T#30M);

        IF tSinterPlateauDwell.Q THEN
            tSinterPlateauDwell(IN := FALSE);
            iState := 60;
        END_IF;

    60: (* ---------------- CONTROLLED HIGH-VACUUM RADIATIVE COOLING ---------------- *)
        bMicrowaveHighVoltageEnable := FALSE;
        rForwardPowerDemand_kW      := 0.0;
        rCryoThrottleValve_Pct      := 100.0; (* Maintain high vacuum during cooling to prevent Fe0 oxidation *)

        tCoolingThermalDecay(IN := (rCoreTemp_Voted_DegC < 85.0), PT := T#5M);

        IF tCoolingThermalDecay.Q THEN
            tCoolingThermalDecay(IN := FALSE);
            iState := 70;
        END_IF;

    70: (* ---------------- CHAMBER VENTING & CONTROLLED GN2 PURGE ---------------- *)
        bMicrowaveHighVoltageEnable := FALSE;
        rForwardPowerDemand_kW      := 0.0;
        rCryoThrottleValve_Pct      := 0.0;  (* Isolate cryopump before backfill *)
        bPurgeGasValve_Cmd          := TRUE; (* Open purge valve *)

        tChamberVentingTimer(IN := (rChamberPressure_Voted_Torr >= 750.0), PT := T#2M);

        IF tChamberVentingTimer.Q THEN
            tChamberVentingTimer(IN := FALSE);
            bPurgeGasValve_Cmd := FALSE;
            iState := 0; (* Process complete, return to idle *)
        END_IF;

    90: (* ---------------- PLASMA ARC SUPPRESSION & FAST RECOVERY ---------------- *)
        bMicrowaveHighVoltageEnable := FALSE;
        rForwardPowerDemand_kW      := 0.0;
        rCryoThrottleValve_Pct      := 100.0;

        tArcSuppressionQuench(IN := TRUE, PT := T#3S);

        IF tArcSuppressionQuench.Q THEN
            tArcSuppressionQuench(IN := FALSE);
            IF NOT bArcLockoutActive AND bWindowArcDetected THEN
                iState := 40; (* Resume dynamic sintering ramp *)
            ELSE
                bAlarmAggregatedFault := TRUE;
                iState := 99; (* Lockout trip *)
            END_IF;
        END_IF;

    99: (* ---------------- CRITICAL EMERGENCY SHUTDOWN LOCKOUT ---------------- *)
        bMicrowaveHighVoltageEnable := FALSE;
        rForwardPowerDemand_kW      := 0.0;
        bRoughingPumpValve_Cmd      := FALSE;
        rCryoThrottleValve_Pct      := 0.0;
        bPurgeGasValve_Cmd          := FALSE;
        bAlarmAggregatedFault       := TRUE;

        IF NOT bEmergencyStop THEN
            (* Hardware E-stop acknowledged *)
            iState := 99;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
